use super::*;
use crate::{npc::{Npc,Restrict,BlockWalk},ducks::Config};
struct Draws(VecDeque<(u32,u32)>);
impl RandomSource for Draws{fn below(&mut self,b:u32)->u32{let(k,v)=self.0.pop_front().expect("Unexpected duck random draw");assert_eq!(b,k);assert!(v<b);v}}
fn empty()->Draws{Draws(VecDeque::new())}
fn world()->World{let mut w=World::default();for x in(3184..3232).step_by(8){for z in(3184..3232).step_by(8){w.collision.allocate(x,z,0);}}w.ducks=Some(Config{adults:[1838,1839].into(),male:1838,female:1839,ducklings:2002,sound:413});w.npc_no_death_drops=[1838,1839].into();w}
fn spawn(w:&mut World,raw:u16,x:i32,z:i32)->NpcId{let mut n=Npc::new(raw,CoordGrid::new(x,z,0).unwrap(),1,Restrict::Normal,BlockWalk::Npc).unwrap();n.mode=Mode::None;n.regen_rate=0;n.ai_timer=-1;n.stats[3]=3;n.base_stats[3]=3;w.spawn_npc(n).unwrap()}
fn sayings(w:&mut World)->Vec<(NpcId,&'static str)>{w.drain_events().into_iter().filter_map(|e|if let WorldEvent::NpcOverhead{actor,text}=e{Some((actor,text))}else{None}).collect()}
#[test]
fn duck_all_51_interval_draws_use_same_phase_one_cycle_queue(){for draw in 0..51{let mut w=world();let a=spawn(&mut w,1838,3203,3203);w.npc_mut(a).unwrap().ai_timer=1;w.drain_events();let mut rng=Draws([(51,draw)].into());w.tick_with_random(&mut rng).unwrap();assert!(rng.0.is_empty());assert_eq!(w.npc(a).unwrap().ai_timer,50+draw as i32);let e=w.drain_events();assert_eq!(e.iter().filter(|e|matches!(e,WorldEvent::NpcOverhead{actor,text:"Quack!"}if *actor==a)).count(),1);assert_eq!(e.iter().filter(|e|matches!(e,WorldEvent::AreaSound(s)if s.id==413&&s.radius==5&&s.delay==0&&s.loops==1&&s.size==0)).count(),1);}}
#[test]
fn duckling_mother_los_call_and_one_later_phase_answer(){let mut w=world();let child=spawn(&mut w,2002,3203,3203);let mother=spawn(&mut w,1839,3205,3203);w.npc_mut(child).unwrap().ai_timer=1;w.drain_events();w.tick_with_random(&mut Draws([(51,7)].into())).unwrap();assert_eq!(sayings(&mut w),vec![(mother,"Quack?")]);w.tick_with_random(&mut empty()).unwrap();assert_eq!(sayings(&mut w),vec![(child,"Eep!")]);w.tick_with_random(&mut empty()).unwrap();assert!(sayings(&mut w).is_empty());}
#[test]
fn duck_los_query_filters_blocked_nearest_and_keeps_visible_dying_candidates(){let mut w=world();let at=CoordGrid::new(3203,3203,0).unwrap();let near=spawn(&mut w,1839,3204,3203);let far=spawn(&mut w,1839,3203,3206);w.collision.add(3204,3203,0,0x10000);assert_eq!(w.find_npc(at,1839,10).unwrap(),Some(near));assert_eq!(w.find_npc_line_of_sight(at,1839,10).unwrap(),Some(far));assert_eq!(w.find_all_npcs_line_of_sight(at,1839,10).unwrap(),vec![far]);w.collision.remove(3204,3203,0,0x10000);w.npc_mut(near).unwrap().stats[3]=0;assert_eq!(w.find_npc_line_of_sight(at,1839,10).unwrap(),Some(near));w.npc_mut(near).unwrap().visible=false;assert_eq!(w.find_npc_line_of_sight(at,1839,10).unwrap(),Some(far));assert!(w.find_npc_line_of_sight(CoordGrid::ZERO,1839,10).is_err());}
#[test]
fn duckling_absent_hidden_far_or_occluded_mother_only_reschedules(){for case in 0..4{let mut w=world();let c=spawn(&mut w,2002,3203,3203);let m=spawn(&mut w,1839,if case==2{3214}else{3205},3203);match case{0=>{w.despawn_npc(m);},1=>w.npc_mut(m).unwrap().visible=false,2=>(),_=>w.collision.add(3205,3203,0,0x10000)}w.npc_mut(c).unwrap().ai_timer=1;w.drain_events();w.tick_with_random(&mut Draws([(51,0)].into())).unwrap();assert_eq!(w.npc(c).unwrap().ai_timer,50);assert!(sayings(&mut w).is_empty());for _ in 0..3{w.tick_with_random(&mut empty()).unwrap();assert!(sayings(&mut w).is_empty());}}}
#[test]
fn duck_mourn_append_timing_depends_on_existing_queue_tail(){for pending in[false,true]{let mut w=world();let c=spawn(&mut w,2002,3203,3203);w.queue_duck_callback(c,Callback::Mourn,2);if pending{w.queue_duck_callback(c,Callback::DucklingSay,9);}let mut observed=Vec::new();for clock in 0..=3{w.clock.0=clock;let mut rng=if clock==1{Draws([(361,0)].into())}else{empty()};w.process_duck_callbacks(c,&mut rng);observed.extend(sayings(&mut w).into_iter().map(|(_,text)|(clock,text)));assert!(rng.0.is_empty());}assert_eq!(observed,vec![(1,"Cheep cheep!"),(if pending{2}else{3},"Eep!")]);}}
#[test]
fn duck_mourn_in_active_mode_only_speaks_and_stale_jobs_do_not_reappear(){let mut w=world();let c=spawn(&mut w,2002,3203,3203);w.npc_mut(c).unwrap().mode=Mode::Wander;w.queue_duck_callback(c,Callback::Mourn,1);w.process_duck_callbacks(c,&mut empty());assert_eq!(sayings(&mut w),vec![(c,"Cheep cheep!")]);assert!(w.npcs.get(c.slot as usize).unwrap().duck_jobs.is_empty());w.queue_duck_callback(c,Callback::DucklingSay,2);w.despawn_npc(c);let n=spawn(&mut w,2002,3203,3203);assert_ne!(c,n);for clock in 1..4{w.clock.0=clock;w.process_duck_callbacks(n,&mut empty());assert!(sayings(&mut w).is_empty());}}
#[test]
fn duck_mourn_square_filters_after_without_replacement_draws(){let mut w=world();let at=CoordGrid::new(3203,3203,0).unwrap();let mut rng=Draws([(361,180),(360,0)].into());assert_eq!(w.duck_mourn_square(at,&mut rng),Some(CoordGrid::new(3194,3194,0).unwrap()));assert!(rng.0.is_empty());w.collision.add(3194,3194,0,0x200000);let mut rng=Draws([(361,0),(360,180),(359,1)].into());assert_eq!(w.duck_mourn_square(at,&mut rng),Some(CoordGrid::new(3195,3194,0).unwrap()));assert!(rng.0.is_empty());assert_eq!(w.duck_mourn_square(CoordGrid::new(8,3203,0).unwrap(),&mut empty()),None);}
#[test]
fn duck_queue_matches_actual_kotlin_list_processor_phase_tail_pause_and_reset_fixtures(){
    struct Zero;impl RandomSource for Zero{fn below(&mut self,_:u32)->u32{0}}
    for line in include_str!("fixtures/duck-queue-source.expected").lines(){let f=line.split('|').collect::<Vec<_>>();assert_eq!(f.len(),3);let name=f[0];let adult=name.starts_with("adult")||name=="paused";let mut w=world();let mut actor=spawn(&mut w,if adult{1838}else{2002},3203,3203);let say=if adult{Callback::AdultSay}else{Callback::DucklingSay};
        match name{"adult-one"|"paused"=>w.queue_duck_callback(actor,say,1),"adult-two"|"child-two"=>w.queue_duck_callback(actor,say,2),"mourn"|"mourn-wander"=>w.queue_duck_callback(actor,Callback::Mourn,2),"mourn-tail"=>{w.queue_duck_callback(actor,Callback::Mourn,2);w.queue_duck_callback(actor,say,9);},"mourn-pair"=>{w.queue_duck_callback(actor,Callback::Mourn,2);w.queue_duck_callback(actor,Callback::Mourn,2);},"cleared"=>w.queue_duck_callback(actor,say,3),"mourn-late"=>(),_=>panic!("Unknown source fixture")}
        if name=="mourn-wander"{w.npc_mut(actor).unwrap().mode=Mode::Wander;}let mut observed=Vec::new();
        for clock in 0..=4{w.clock.0=clock;if name=="cleared"&&clock==1{w.despawn_npc(actor);actor=spawn(&mut w,2002,3203,3203);}w.npc_mut(actor).unwrap().delayed=name=="paused"&&clock<3;w.process_duck_callbacks(actor,&mut Zero);observed.extend(sayings(&mut w).into_iter().map(|(_,t)|format!("{clock}:{t}")));if name=="mourn-late"&&clock==0{w.queue_duck_callback(actor,Callback::Mourn,2);}}
        let pending=w.npcs.get(actor.slot as usize).unwrap().duck_jobs.iter().map(|j|format!("{}:{}:{}",if matches!(j.callback,Callback::Mourn){2}else{1},j.remaining,j.processed_cycle)).collect::<Vec<_>>().join(";");assert_eq!(observed.join(";"),f[1],"actual Kotlin queue events {name}");assert_eq!(pending,f[2],"actual Kotlin queue tail {name}");
    }
}
#[test]
fn duck_authoritative_death_reacts_once_and_suppresses_only_duck_remains(){for raw in[1839,1]{let mut w=world();w.npc_death=Some(crate::npc_death::Config{definitions:[(1838,crate::npc_death::Definition{animation:3468,animation_ticks:1,sound:None}),(1839,crate::npc_death::Definition{animation:3468,animation_ticks:1,sound:None}),(1,crate::npc_death::Definition{animation:3468,animation_ticks:1,sound:None})].into(),bones:526,chickens:Default::default()});let dead=spawn(&mut w,raw,3203,3203);w.npc_mut(dead).unwrap().respawns=false;let male=spawn(&mut w,1838,3203,3204);let child=spawn(&mut w,2002,3204,3203);w.queue_login(1,PlayerData::new(1,"Duck death fixture".into(),CoordGrid::new(3201,3203,0).unwrap(),crate::stats::Stats::default())).unwrap();w.tick_with_random(&mut empty()).unwrap();let actor=w.actors().next().unwrap();w.set_observer_id(actor,42).unwrap();w.drain_events();let uuid=w.data(actor).unwrap().character_id;w.npc_mut(dead).unwrap().hero_points.credit(uuid,3);assert_eq!(w.npc(dead).unwrap().hero_points.winner(),Some(uuid));w.queue_hit(crate::hits::Target::Npc(dead),crate::hits::Hit{display:None,source:Some(crate::hits::Target::Player(actor)),style:crate::hits::Style::Typeless,damage:3},0).unwrap();let mut seen=Vec::new();for step in 0..6{let mut rng=if raw==1839&&step==1{Draws([(361,0)].into())}else{empty()};w.tick_with_random(&mut rng).unwrap();seen.extend(sayings(&mut w));assert!(rng.0.is_empty());}if raw==1839{assert_eq!(seen.iter().filter(|(id,t)|*id==male&&*t=="Quack!").count(),1);assert_eq!(seen.iter().filter(|(id,t)|*id==child&&*t=="Cheep cheep!").count(),1);assert_eq!(seen.iter().filter(|(id,t)|*id==child&&*t=="Eep!").count(),1);assert_eq!(w.objects.count(),0);}else{assert!(seen.is_empty());assert_eq!(w.objects.count(),1);}}}
